CREATE TABLE public.rtc_closed_rooms(room_id uuid PRIMARY KEY,closed_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rtc_closed_rooms TO service_role;
ALTER TABLE public.rtc_closed_rooms ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.rtc_close_room(_room uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room AND host_id=auth.uid()) THEN RAISE EXCEPTION 'Somente o anfitrião pode encerrar'; END IF; INSERT INTO rtc_closed_rooms(room_id) VALUES(_room) ON CONFLICT DO NOTHING; DELETE FROM rtc_rooms WHERE id=_room AND host_id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.rtc_close_room(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rtc_close_room(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.rtc_guarded_exchange(_room uuid,_peer uuid,_op text DEFAULT 'poll',_name text DEFAULT '',_since bigint DEFAULT 0,_to uuid DEFAULT NULL,_kind text DEFAULT NULL,_payload jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF; PERFORM pg_advisory_xact_lock(hashtext(_room::text)); IF EXISTS(SELECT 1 FROM rtc_closed_rooms WHERE room_id=_room) THEN RAISE EXCEPTION 'Convite encerrado'; END IF; IF EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room AND expires_at<=now()) THEN INSERT INTO rtc_closed_rooms(room_id) VALUES(_room) ON CONFLICT DO NOTHING; RETURN jsonb_build_object('closed',true,'peers','[]'::jsonb,'signals','[]'::jsonb); END IF; IF _op='poll' THEN PERFORM consume_action_budget('rtc_poll',300,60); IF NOT EXISTS(SELECT 1 FROM rtc_rooms WHERE id=_room) THEN PERFORM consume_action_budget('rtc_create',5,3600); END IF; ELSIF _op='signal' THEN PERFORM consume_action_budget('rtc_signal',120,60); END IF; RETURN rtc_exchange(_room,_peer,_op,_name,_since,_to,_kind,_payload); END $$;
REVOKE ALL ON FUNCTION public.rtc_guarded_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rtc_guarded_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) TO service_role;